CREATE TABLE "public"."Activity_profile" (
  "id"                       bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "activity_level"           text   NOT NULL,
  "workouts_per_week"        bigint,
  "preferred_exercise_types" text,
  "daily_step_goal"          bigint,
  CONSTRAINT "Activity_profile_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."Activity_profile"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."Dietary_preferences" (
  "id"                   bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "diet_type"            timestamp with time zone NOT NULL DEFAULT now(),
  "dietary_restrictions" text,
  "food_allergies"       text,
  "excluded_foods"       text,
  CONSTRAINT "Dietary_preferences_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."Dietary_preferences"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."Recipe" (
  "id"                 bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_at"         timestamp with time zone NOT NULL DEFAULT now(),
  "Name"               text,
  "Link"               text,
  "Diet type"          text[],
  "Meal Type"          character varying,
  "Symbols"            integer[]                DEFAULT '{0}'::integer[],
  "Kitchen Appliances" text[],
  "Cuisine"            text,
  "Nutrition"          real[],
  "Ingredients"        text[],
  "Time"               integer,
  CONSTRAINT "Recipe_Name_key" UNIQUE ("Name"),
  CONSTRAINT "Recipe_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."Recipe"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."Users" (
  "id"                   bigint                   GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "public"."User_id_seq") NOT NULL,
  "created_at"           timestamp with time zone NOT NULL DEFAULT now(),
  "weight"               real,
  "height"               real,
  "dietary restrictions" text[],
  "disliked ingredients" text[],
  "kitchen appliances"   text[],
  "primary goal"         text,
  "stats preferences"    text[],
  "user_id"              bigint,
  "username"             text,
  "display_name"         text,
  "email"                text                     NOT NULL,
  CONSTRAINT "User_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."Users"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."user_goals" (
  "id"              bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "primary_goal"    timestamp with time zone NOT NULL DEFAULT now(),
  "secondary_goals" text,
  "target_weight"   text,
  "goal_start_date" text,
  "goal_updated_at" text,
  CONSTRAINT "user_goals_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."user_goals"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."user_profile" (
  "user_id"               bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "age"                   bigint                   NOT NULL,
  "sex"                   text,
  "height_cm"             bigint,
  "current_weight"        bigint,
  "preferred_height_unit" text                     DEFAULT 'inches'::text,
  "preferred_weight_unit" text                     DEFAULT 'pounds'::text,
  "updated_at"            timestamp with time zone,
  CONSTRAINT "user_profile_pkey" PRIMARY KEY (user_id)
);

ALTER TABLE "public"."user_profile"
  ENABLE ROW LEVEL SECURITY;

COMMENT ON COLUMN "public"."Users"."email" IS 'email address used';

COMMENT ON COLUMN "public"."Users"."user_id" IS 'Unique identifier for user';

COMMENT ON COLUMN "public"."Users"."username" IS 'User can optionally select a username for their profile';

COMMENT ON TABLE "public"."Activity_profile" IS 'Contains users acvitivity level, workouts per week, exercise types, and daily step goal';

COMMENT ON TABLE "public"."Dietary_preferences" IS 'Contains information for user diet type restrictions, food allergies and excluded foods';

COMMENT ON TABLE "public"."Recipe" IS 'Table containing all app recipes and their corresponding information.';

COMMENT ON TABLE "public"."Users" IS 'Table containing all user specific information of all app users.';

COMMENT ON TABLE "public"."user_goals" IS 'Contains the goals that the user has set';

COMMENT ON TABLE "public"."user_profile" IS 'Contains information on users such as age sex height weight etc';

